#include <iostream>
#include <string>
#include <vector>

std::vector<std::string> timesTable(int n) {
    std::vector<std::string> lines;
    for (int i = 1; i <= 10; i++) {
        lines.push_back(std::to_string(n) + " x " + std::to_string(i) + " = " +
                        std::to_string(n * i));
    }
    return lines;
}

int main() {
    int n;
    std::cin >> n;
    for (const std::string& line : timesTable(n)) {
        std::cout << line << "\n";
    }
    return 0;
}

