package main

import "fmt"

func timesTable(n int) []string {
	lines := []string{}
	for i := 1; i <= 10; i++ {
		lines = append(lines, fmt.Sprintf("%d x %d = %d", n, i, n*i))
	}
	return lines
}

func main() {
	var n int
	fmt.Scan(&n)
	for _, line := range timesTable(n) {
		fmt.Println(line)
	}
}

